entries[218415] = { ["name"] = "Todesblüte", ["text"] = "Wirken in 15 sek.\nErschafft eine Todesblüte an einem Ort. Nach 15 Sek. detoniert sie und fügt allen Spielercharakteren, die auf der Blüte stehen, 10273 Schattenschaden zu und erhöht ihre Bewegungsgeschwindigkeit für 6 Sek. um 50%.\n\nWenn kein Spielercharakter von der Detonation der Todesblüte getroffen wird, explodiert sie in einem großen Bereich und belegt alle Spielercharaktere mit 'Sporenstaub'." }
