entries[218681] = { ["name"] = "Champion: Allari die Seelenfresserin", ["text"] = "Sofort\nAllari die Seelenfresserin ist die Trägerin des Artefakts, das als die Seelensense bekannt ist. Zusätzlich zu ihrer eigenen meisterhaften Beherrschung des Einfangens von Dämonenseelen gewährt ihr die Sense noch weitere unglaubliche Kräfte. Nur wenige andere sind so effektiv darin, die Brennende Legion in die Knie zu zwingen." }
entries[218682] = { ["name"] = "Champion: Jace Düsterweber", ["text"] = "Sofort\nIn seinem alten Leben, bevor er sich den ritualhaften Veränderungen unterwarf, die ihn zu einem Illidari machten, war Jace ein mächtiger Magier. Auch heute verfügt er noch über einen Großteil seines Wissens um die Magie. Durch dieses Wissen und seine Macht über die Teufelsenergien, die seinen Körper durchströmen, konnte er viele nützliche Gerätschaften für die Illidari erschaffen, wie die Nethertiegel, Dämonenfallen und Zauberschutze." }
